package com.hbm.satellite.link.client;
import com.hbm.satellite.link.*;import net.minecraft.ChatFormatting;import net.minecraft.nbt.*;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import snownee.jade.api.*;import snownee.jade.api.config.IPluginConfig;
@WailaPlugin public final class SatelliteLinkJade implements IWailaPlugin{
 @Override public void register(IWailaCommonRegistration event){event.registerBlockDataProvider(Data.INSTANCE,SatelliteLinkBlockEntity.class);event.registerBlockDataProvider(Data.INSTANCE,SatelliteLinkPort.class);}@Override public void registerClient(IWailaClientRegistration event){event.registerBlockComponent(Data.INSTANCE,SatelliteLinkBlock.class);}private enum Data implements IServerDataProvider<BlockAccessor>,IBlockComponentProvider{INSTANCE;@Override public ResourceLocation getUid(){return ResourceLocation.parse("hbm:satellite_link_state");}@Override public void appendServerData(CompoundTag tag,BlockAccessor accessor){var tile=accessor.getBlockEntity();if(tile instanceof SatelliteLinkPort port)tile=port.core();if(tile instanceof SatelliteLinkBlockEntity link){tag.putInt("hbm:sat_freq",link.freq);tag.putBoolean("hbm:sat_connected",link.connected);var list=new ListTag();for(var info:link.info)if(info!=null)list.add(StringTag.valueOf(Component.Serializer.toJson(info,accessor.getLevel().registryAccess())));tag.put("hbm:sat_info",list);}}@Override public void appendTooltip(ITooltip tooltip,BlockAccessor accessor,IPluginConfig config){var tag=accessor.getServerData();if(!tag.contains("hbm:sat_freq"))return;tooltip.add(Component.translatable("tile.machine_satlink.freq").append(": "+tag.getInt("hbm:sat_freq")));boolean connected=tag.getBoolean("hbm:sat_connected");tooltip.add(Component.translatable("tile.machine_satlink.connected").append(": ").append(Component.translatable("tile.machine_satlink."+(connected?"yes":"no")).withStyle(connected?ChatFormatting.GREEN:ChatFormatting.RED)));var list=tag.getList("hbm:sat_info",Tag.TAG_STRING);for(int i=0;i<list.size();i++){var line=Component.Serializer.fromJson(list.getString(i),accessor.getLevel().registryAccess());if(line!=null)tooltip.add(line);}}}
}
